import java.util.ArrayList;
import java.util.Iterator;
public class Main { public static void main(String[] args) { ArrayList<String> names = new ArrayList<>(); names.add("Ana"); names.add("Ben"); Iterator<String> it = names.iterator(); while (it.hasNext()) System.out.println(it.next()); } }

import java.util.ArrayList;
import java.util.Iterator;
public class Main { public static void main(String[] args) { ArrayList<Integer> nums = new ArrayList<>(); nums.add(1); nums.add(2); nums.add(3); Iterator<Integer> it = nums.iterator(); while (it.hasNext()) if (it.next() % 2 == 0) it.remove(); System.out.println(nums); } }

import java.util.ArrayList;
import java.util.Iterator;
public class Main { public static void main(String[] args) { ArrayList<String> words = new ArrayList<>(); words.add("one"); words.add("two"); words.add("three"); int count = 0; for (Iterator<String> it = words.iterator(); it.hasNext(); ) { it.next(); count++; } System.out.println(count); } }

import java.util.ArrayList;
import java.util.Iterator;
public class Main { public static void main(String[] args) { ArrayList<Integer> values = new ArrayList<>(); values.add(4); values.add(8); values.add(12); Iterator<Integer> it = values.iterator(); while (it.hasNext()) { int v = it.next(); if (v == 8) break; System.out.println(v); } } }

import java.util.HashSet;
import java.util.Iterator;
public class Main { public static void main(String[] args) { HashSet<String> codes = new HashSet<>(); codes.add("IN"); codes.add("US"); Iterator<String> it = codes.iterator(); int count = 0; while (it.hasNext()) { it.next(); count++; } System.out.println(count); } }
